Output120[Expected Approach] Binary Search – O(n × log2(max(heights[i]) - min(heights[i])) Time and O(1) Space  At minimum or maximum heights, the cost increases due to many changes in heights. As we move toward a balanced height, the cost drops, reaches a minimum, then rises again — forming a V-shape. We use binary search by checking mid - 1, mid, and mid + 1 to move toward the side with lower cost and find the minimum cost efficiently.Step by step approach:Find the minimum and maximum height in the heights[] array and use them as the initial range for binary search.Apply binary search on this range. For each mid-point mid, calculate the total cost of making all towers of height: mid - 1, mid, mid + 1Check these cases:=> If findCost(mid) ≤ findCost(mid - 1) and findCost(mid) ≤ findCost(mid + 1),→ mid gives the minimum cost, return it.=> If findCost(mid) ≤ findCost(mid - 1) and findCost(mid + 1) < findCost(mid), → Move right: set low = mid + 1 (we are in the decreasing part of the cost curve).=> If findCost(mid - 1) < findCost(mid), → Move left: set high = mid - 1 (we are in the increasing part of the cost curve).Repeat until the minimum cost is found.
            C++

    #include <iostream>
#include <vector>
#include <climits>
#include <algorithm>
using namespace std;

// calculate total cost to make all towers height h
int findCost(vector<int> &heights, vector<int> &cost, int h) {
    int res = 0;
    int n = heights.size();
    for (int i = 0; i < n; i++) {
        res += cost[i] * abs(heights[i] - h);
    }
    return res;
}

// return minimum cost to make all towers same height
int minCost(vector<int> &heights, vector<int> &cost) {
    int n = heights.size();

    // find min and max height
    int mini = INT_MAX, maxi = INT_MIN;
    for (auto val : heights) {
        mini = min(mini, val);
        maxi = max(maxi, val);
    }

    int low = mini, high = maxi;
    int ans;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        int val1 = findCost(heights, cost, mid - 1);
        int val2 = findCost(heights, cost, mid);
        int val3 = findCost(heights, cost, mid + 1);

        // if mid gives lowest cost
        if (val2 <= val1 && val2 <= val3) {
            ans = val2;
            break;
        }
        // if decreasing side gives less cost
        else if (val1 >= val2 && val2 >= val3) {
            low = mid + 1;
        }
        // if increasing side gives less cost
        else if (val2 >= val1 && val3 >= val2) {
            high = mid - 1;
        }
    }

    return ans;
}

int main() {
    vector<int> heights = {1, 2, 3};
    vector<int> cost = {10, 100, 1000};
    cout << minCost(heights, cost);
    return 0;
}


