Output120[Alternate Approach] Ternary SearchAt low or high heights, the cost increases due to excessive changes in heights. As we move toward an optimal height, the cost decreases, reaches a minimum, then increases again — forming a V-shape (unimodal  pattern). This allows us to use Ternary search to efficiently find the minimum cost.Step by step approach:Each tower must be adjusted to a target height with cost: abs(height - target) * cost.The target height will always lie between the minimum and maximum of the given tower heights.The total cost function is unimodal, it decreases, reaches a minimum, then increases.Therefore, ternary search is used to efficiently find the minimum cost.In each step, two midpoints are chosen, and total cost is calculated at both.If both costs are equal, shrink both ends of the range.If the left cost is smaller, discard the right part.If the right cost is smaller, discard the left part.After the search ends, the minimum cost found is the final answer.
            C++

    #include <iostream>
#include <vector>
#include <climits>
#include <algorithm>
using namespace std;

// helper function to calculate the cost of making all towers
// equal to a specific target height
int costOfOperation(vector<int>& heights, vector<int>& cost,
                                                    int target) {

    int totalCost = 0;
    int n = heights.size();
    for (int i = 0; i < n; i++) {
        // Cost is the absolute height difference 
        // multiplied by the cost factor
        totalCost += abs(heights[i] - target) * cost[i];
    }
    return totalCost;

}

// ternary Search function to find the height
// that minimizes the total cost
int minCost(vector<int>& heights, vector<int>& cost) {
    // set the search space between the minimum and
    // maximum tower height
    int low = *min_element(heights.begin(), heights.end());
    int high = *max_element(heights.begin(), heights.end());
    int minimumCost = INT_MAX;

    // perform ternary Search within the height range
    while (low <= high) {
        int mid1 = low + (high - low) / 3;
        int mid2 = high - (high - low) / 3;

        // calculate cost at mid1 and mid2
        int cost1 = costOfOperation(heights, cost, mid1);
        int cost2 = costOfOperation(heights, cost, mid2);

        // track the minimum cost found so far
        minimumCost = min({minimumCost, cost1, cost2});

        // narrow the search space based on comparison
        if (cost1 == cost2) {

            // If costs are equal, we shrink both sides
            low = mid1 + 1;
            high = mid2 - 1;
        }
        else if (cost1 < cost2) {
            // optimal cost is towards the left half
            high = mid2 - 1;
        }
        else {
            // optimal cost is towards the right half
            low = mid1 + 1;
        }
    }

    return minimumCost;
}

int main() {
    vector<int> heights = {1, 2, 3};
    vector<int> cost = {10, 100, 1000};
    cout << minCost(heights, cost);
    return 0;
}


